import os, re, json
from pathlib import Path

repo = Path('/tmp/stingallo_1crn/Exosite-STING-ML-Prediction')
print('=== Paths containing 1CRN ===')
hits = []
for p in repo.rglob('*'):
    if '1crn' in p.name.lower():
        hits.append(p)
for p in hits:
    print(p.relative_to(repo), '(dir)' if p.is_dir() else f'({p.stat().st_size} bytes)')

print('\n=== Contents of 1CRN-related files/directories ===')
for p in hits:
    if p.is_dir():
        for child in sorted(p.rglob('*')):
            if child.is_file():
                print('\n---', child.relative_to(repo), f'({child.stat().st_size} bytes) ---')
                text = child.read_text(errors='ignore')
                print(text[:12000])
    elif p.stat().st_size < 2_000_000:
        print('\n---', p.relative_to(repo), f'({p.stat().st_size} bytes) ---')
        print(p.read_text(errors='ignore')[:12000])

print('\n=== Key source files around residue parsing/output ===')
for rel in ['DCC.py','annotate_exosite.py','FPocket_for_test_subset.py','README.md']:
    p = repo / rel
    if not p.exists():
        continue
    lines = p.read_text(errors='ignore').splitlines()
    print(f'\n--- {rel} ---')
    for i,line in enumerate(lines,1):
        if re.search(r'residue|res_id|index|number|pdb_code|allosteric', line, re.I):
            print(f'{i:04d}: {line}')
